//! Typed access to Bazel runfiles.
//!
//! Code generated by `rust_runfile_library` declares one static spec per
//! runfile: a [`FileSpec`], [`ExecutableSpec`], [`DirectorySpec`], or
//! [`FileSetSpec`]. A spec holds only the runfile's rlocation path, so
//! declaring it does no I/O. Calling `resolve()` looks the runfile up and
//! returns a resolved [`File`], [`Executable`], [`Directory`], or [`FileSet`].
//! Resolution is the only step that can fail.
//!
//! Lookups go through the [`runfiles`] crate from
//! [rules_rust](https://github.com/bazelbuild/rules_rust/tree/main/rust/runfiles).
//! It supports both a runfiles directory and a manifest-only setup.
//!
//! For background on rlocation paths and the runfiles tree, see
//! [Bazel runfiles](https://bazel.build/extending/rules#runfiles).

use std::collections::BTreeMap;
use std::ffi::OsString;
use std::fmt;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::{Arc, OnceLock};

const RUNFILES_DIR: &str = "RUNFILES_DIR";
const RUNFILES_MANIFEST_FILE: &str = "RUNFILES_MANIFEST_FILE";
const JAVA_RUNFILES: &str = "JAVA_RUNFILES";

/// The error returned when a runfile cannot be resolved.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum Error {
    /// The default resolver could not find the runfiles directory or
    /// manifest of the running program.
    Init(Arc<runfiles::RunfilesError>),
    /// The runfile is not in the runfiles directory or manifest.
    NotFound {
        /// The rlocation path that was looked up.
        rlocation_path: String,
    },
    /// A relative path was requested from a [`FileSet`] that does not
    /// contain it.
    NotInFileSet {
        /// The relative path that was requested.
        rel_path: String,
    },
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Init(err) => write!(f, "cannot initialize Bazel runfiles: {err}"),
            Error::NotFound { rlocation_path } => {
                write!(f, "runfile {rlocation_path:?} not found")
            }
            Error::NotInFileSet { rel_path } => {
                write!(f, "file {rel_path:?} is not in this file set")
            }
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Error::Init(err) => Some(err.as_ref()),
            _ => None,
        }
    }
}

/// Looks up runfiles by rlocation path.
///
/// [`BazelRunfiles`] is the implementation used by `resolve()`. Pass another
/// implementation to `resolve_with()` to substitute paths in unit tests.
pub trait Resolver {
    /// Returns the path of the runfile at `rlocation_path`, or `None` if the
    /// runfile is unknown.
    ///
    /// `rlocation_path` is canonical: it starts with a canonical repository
    /// name such as `_main`. The returned path does not have to exist; the
    /// caller checks that.
    fn rlocation(&self, rlocation_path: &str) -> Option<PathBuf>;

    /// Returns the environment variables that let a child process find the
    /// same runfiles.
    ///
    /// The default returns no variables.
    fn env_vars(&self) -> Vec<(OsString, OsString)> {
        Vec::new()
    }
}

/// The runfiles of the running program, found the way Bazel describes for
/// [runfiles libraries](https://bazel.build/extending/rules#runfiles).
#[derive(Debug)]
pub struct BazelRunfiles {
    runfiles: runfiles::Runfiles,
    env: Vec<(OsString, OsString)>,
}

impl BazelRunfiles {
    /// Finds the runfiles of the running program.
    ///
    /// It uses `RUNFILES_MANIFEST_FILE` if set, then `RUNFILES_DIR` or
    /// `TEST_SRCDIR`, then a `<program>.runfiles` directory or
    /// `<program>.runfiles_manifest` file next to the program.
    pub fn create() -> Result<Self, Error> {
        let runfiles = runfiles::Runfiles::create().map_err(|err| Error::Init(Arc::new(err)))?;
        Ok(BazelRunfiles {
            runfiles,
            env: child_env(),
        })
    }
}

impl Resolver for BazelRunfiles {
    fn rlocation(&self, rlocation_path: &str) -> Option<PathBuf> {
        // Generated rlocation paths are canonical, so no repository mapping
        // applies.
        let path = self.runfiles.rlocation(rlocation_path)?;
        Some(std::path::absolute(&path).unwrap_or(path))
    }

    fn env_vars(&self) -> Vec<(OsString, OsString)> {
        self.env.clone()
    }
}

/// Computes the runfiles variables for a child process.
///
/// The paths are made absolute so that a child started in another working
/// directory still finds them.
fn child_env() -> Vec<(OsString, OsString)> {
    let mut env = Vec::new();
    let mut push = |key: &str, path: &Path| {
        let path = std::path::absolute(path).unwrap_or_else(|_| path.to_path_buf());
        env.push((OsString::from(key), path.into_os_string()));
    };

    if let Some(manifest) = std::env::var_os(RUNFILES_MANIFEST_FILE).filter(|v| !v.is_empty()) {
        push(RUNFILES_MANIFEST_FILE, Path::new(&manifest));
        if let Some(dir) = std::env::var_os(RUNFILES_DIR).filter(|v| !v.is_empty()) {
            push(RUNFILES_DIR, Path::new(&dir));
        }
    } else if let Ok(dir) = runfiles::find_runfiles_dir() {
        push(RUNFILES_DIR, &dir);
        push(JAVA_RUNFILES, &dir);
        let manifest = dir.join("MANIFEST");
        if manifest.is_file() {
            push(RUNFILES_MANIFEST_FILE, &manifest);
        }
    } else if let Some(manifest) = manifest_next_to_program() {
        push(RUNFILES_MANIFEST_FILE, &manifest);
    }
    env
}

/// Returns `<program>.runfiles_manifest` if it exists, checking `argv[0]`
/// and then the resolved executable path.
fn manifest_next_to_program() -> Option<PathBuf> {
    let argv0 = std::env::args_os().next().map(PathBuf::from);
    let exe = std::env::current_exe().ok();
    argv0.into_iter().chain(exe).find_map(|program| {
        let mut name = program.file_name()?.to_owned();
        name.push(".runfiles_manifest");
        let manifest = program.with_file_name(name);
        manifest.is_file().then_some(manifest)
    })
}

/// Returns the shared [`BazelRunfiles`] of the running program.
///
/// The first call finds the runfiles. Later calls return the same value, or
/// the same error.
pub fn default_resolver() -> Result<&'static BazelRunfiles, Error> {
    static DEFAULT: OnceLock<Result<BazelRunfiles, Error>> = OnceLock::new();
    DEFAULT
        .get_or_init(BazelRunfiles::create)
        .as_ref()
        .map_err(Clone::clone)
}

fn lookup(resolver: &dyn Resolver, rlocation_path: &str) -> Result<File, Error> {
    match resolver.rlocation(rlocation_path) {
        Some(path) if path.exists() => Ok(File {
            rlocation_path: rlocation_path.to_owned(),
            path,
        }),
        _ => Err(Error::NotFound {
            rlocation_path: rlocation_path.to_owned(),
        }),
    }
}

/// An unresolved runfile that is a single file.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FileSpec {
    rlocation_path: &'static str,
}

impl FileSpec {
    /// Creates a spec for the runfile at the canonical `rlocation_path`.
    pub const fn new(rlocation_path: &'static str) -> Self {
        FileSpec { rlocation_path }
    }

    /// Returns the canonical rlocation path, for example
    /// `_main/data/config.json`.
    pub const fn rlocation_path(&self) -> &'static str {
        self.rlocation_path
    }

    /// Finds the runfile using [`default_resolver`].
    pub fn resolve(&self) -> Result<File, Error> {
        self.resolve_with(default_resolver()?)
    }

    /// Finds the runfile using `resolver`.
    pub fn resolve_with(&self, resolver: &dyn Resolver) -> Result<File, Error> {
        lookup(resolver, self.rlocation_path)
    }

    /// Like [`FileSpec::resolve`], but panics if the runfile is missing.
    pub fn must_resolve(&self) -> File {
        self.resolve().unwrap_or_else(|err| panic!("{err}"))
    }
}

/// A runfile that was found on disk.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct File {
    rlocation_path: String,
    path: PathBuf,
}

impl File {
    /// Returns the canonical rlocation path the file was found by.
    pub fn rlocation_path(&self) -> &str {
        &self.rlocation_path
    }

    /// Returns the absolute path of the file.
    pub fn path(&self) -> &Path {
        &self.path
    }
}

impl AsRef<Path> for File {
    fn as_ref(&self) -> &Path {
        &self.path
    }
}

/// An unresolved runfile that is an executable target, such as a
/// `rust_binary`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ExecutableSpec {
    file: FileSpec,
}

impl ExecutableSpec {
    /// Creates a spec for the executable at the canonical `rlocation_path`.
    pub const fn new(rlocation_path: &'static str) -> Self {
        ExecutableSpec {
            file: FileSpec::new(rlocation_path),
        }
    }

    /// Returns the canonical rlocation path of the executable.
    pub const fn rlocation_path(&self) -> &'static str {
        self.file.rlocation_path
    }

    /// Finds the executable using [`default_resolver`].
    pub fn resolve(&self) -> Result<Executable, Error> {
        self.resolve_with(default_resolver()?)
    }

    /// Finds the executable using `resolver`.
    ///
    /// [`Executable::command`] passes `resolver.env_vars()` to the child.
    pub fn resolve_with(&self, resolver: &dyn Resolver) -> Result<Executable, Error> {
        Ok(Executable {
            file: self.file.resolve_with(resolver)?,
            env: resolver.env_vars(),
        })
    }

    /// Like [`ExecutableSpec::resolve`], but panics if the executable is
    /// missing.
    pub fn must_resolve(&self) -> Executable {
        self.resolve().unwrap_or_else(|err| panic!("{err}"))
    }
}

/// An executable runfile that was found on disk.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Executable {
    file: File,
    env: Vec<(OsString, OsString)>,
}

impl Executable {
    /// Returns the canonical rlocation path the executable was found by.
    pub fn rlocation_path(&self) -> &str {
        self.file.rlocation_path()
    }

    /// Returns the absolute path of the executable.
    pub fn path(&self) -> &Path {
        self.file.path()
    }

    /// Returns a [`Command`] that runs the executable.
    ///
    /// The command sets `RUNFILES_DIR` or `RUNFILES_MANIFEST_FILE` (and
    /// `JAVA_RUNFILES` with a directory) so that the child finds its own
    /// runfiles, which Bazel places in the parent's runfiles tree.
    pub fn command(&self) -> Command {
        let mut command = Command::new(self.path());
        command.envs(self.env.iter().map(|(k, v)| (k, v)));
        command
    }
}

/// An unresolved runfile that is a directory, produced by a rule that
/// declares a [tree artifact](https://bazel.build/extending/rules#tree_artifacts).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DirectorySpec {
    file: FileSpec,
}

impl DirectorySpec {
    /// Creates a spec for the directory at the canonical `rlocation_path`.
    pub const fn new(rlocation_path: &'static str) -> Self {
        DirectorySpec {
            file: FileSpec::new(rlocation_path),
        }
    }

    /// Returns the canonical rlocation path of the directory.
    pub const fn rlocation_path(&self) -> &'static str {
        self.file.rlocation_path
    }

    /// Finds the directory using [`default_resolver`].
    pub fn resolve(&self) -> Result<Directory, Error> {
        self.resolve_with(default_resolver()?)
    }

    /// Finds the directory using `resolver`.
    pub fn resolve_with(&self, resolver: &dyn Resolver) -> Result<Directory, Error> {
        Ok(Directory {
            file: self.file.resolve_with(resolver)?,
        })
    }

    /// Like [`DirectorySpec::resolve`], but panics if the directory is
    /// missing.
    pub fn must_resolve(&self) -> Directory {
        self.resolve().unwrap_or_else(|err| panic!("{err}"))
    }
}

/// A directory runfile that was found on disk.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Directory {
    file: File,
}

impl Directory {
    /// Returns the canonical rlocation path the directory was found by.
    pub fn rlocation_path(&self) -> &str {
        self.file.rlocation_path()
    }

    /// Returns the absolute path of the directory.
    pub fn path(&self) -> &Path {
        self.file.path()
    }

    /// Returns the file at `rel_path` inside the directory.
    ///
    /// This joins paths and does not check that the file exists.
    pub fn child(&self, rel_path: &str) -> File {
        File {
            rlocation_path: format!("{}/{}", self.file.rlocation_path, rel_path),
            path: self.file.path.join(rel_path),
        }
    }
}

/// An unresolved set of runfiles, keyed by a path relative to the set's base.
///
/// Generated code builds one with [`file_set!`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FileSetSpec {
    files: &'static [(&'static str, &'static str)],
}

impl FileSetSpec {
    /// Creates a spec from `(relative path, canonical rlocation path)` pairs.
    pub const fn new(files: &'static [(&'static str, &'static str)]) -> Self {
        FileSetSpec { files }
    }

    /// Returns the `(relative path, canonical rlocation path)` pairs.
    pub const fn files(&self) -> &'static [(&'static str, &'static str)] {
        self.files
    }

    /// Finds every file in the set using [`default_resolver`].
    pub fn resolve(&self) -> Result<FileSet, Error> {
        self.resolve_with(default_resolver()?)
    }

    /// Finds every file in the set using `resolver`.
    pub fn resolve_with(&self, resolver: &dyn Resolver) -> Result<FileSet, Error> {
        let files = self
            .files
            .iter()
            .map(|(rel, rlocation_path)| Ok((*rel, lookup(resolver, rlocation_path)?)))
            .collect::<Result<_, Error>>()?;
        Ok(FileSet { files })
    }

    /// Like [`FileSetSpec::resolve`], but panics if a file is missing.
    pub fn must_resolve(&self) -> FileSet {
        self.resolve().unwrap_or_else(|err| panic!("{err}"))
    }
}

/// Builds a [`FileSetSpec`] in a `static` from `"relative path" =>
/// "rlocation path"` pairs.
///
/// ```
/// static DATA: runfile::FileSetSpec = runfile::file_set! {
///     "a.txt" => "_main/data/a.txt",
///     "b.txt" => "_main/data/b.txt",
/// };
/// assert_eq!(DATA.files().len(), 2);
/// ```
#[macro_export]
macro_rules! file_set {
    ($($rel:literal => $rlocation_path:literal),* $(,)?) => {
        $crate::FileSetSpec::new(&[$(($rel, $rlocation_path)),*])
    };
}

/// A set of runfiles that were all found on disk.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FileSet {
    files: BTreeMap<&'static str, File>,
}

impl FileSet {
    /// Returns the relative paths in the set, in sorted order.
    pub fn rel_paths(&self) -> impl Iterator<Item = &'static str> + '_ {
        self.files.keys().copied()
    }

    /// Returns the file at `rel_path`.
    pub fn file(&self, rel_path: &str) -> Result<&File, Error> {
        self.files.get(rel_path).ok_or_else(|| Error::NotInFileSet {
            rel_path: rel_path.to_owned(),
        })
    }

    /// Like [`FileSet::file`], but panics if the set has no such file.
    pub fn must_file(&self, rel_path: &str) -> &File {
        self.file(rel_path).unwrap_or_else(|err| panic!("{err}"))
    }

    /// Returns the `(relative path, file)` pairs, sorted by relative path.
    pub fn iter(&self) -> impl Iterator<Item = (&'static str, &File)> + '_ {
        self.files.iter().map(|(rel, file)| (*rel, file))
    }
}
